import 'package:cloud_firestore/cloud_firestore.dart';

class AurenFoodItem { final String id,ownerId,name,category,city,country,currency,status; final int priceMinor; final bool halal,organic,vegan,vegetarian,athleteFriendly,highProtein,glutenFree,lactoseFree,lowSugar; final List<String> tags; const AurenFoodItem({required this.id,required this.ownerId,required this.name,required this.category,required this.city,required this.country,required this.currency,required this.priceMinor,required this.halal,required this.organic,required this.vegan,required this.vegetarian,required this.athleteFriendly,required this.highProtein,required this.glutenFree,required this.lactoseFree,required this.lowSugar,required this.tags,required this.status}); factory AurenFoodItem.fromDoc(DocumentSnapshot<Map<String,dynamic>> d){final x=d.data()??{};return AurenFoodItem(id:d.id,ownerId:x['ownerId']??'',name:x['name']??'',category:x['category']??'food',city:x['city']??'',country:x['country']??'',currency:x['currency']??'USD',priceMinor:x['priceMinor']??0,halal:x['halal']==true,organic:x['organic']==true,vegan:x['vegan']==true,vegetarian:x['vegetarian']==true,athleteFriendly:x['athleteFriendly']==true,highProtein:x['highProtein']==true,glutenFree:x['glutenFree']==true,lactoseFree:x['lactoseFree']==true,lowSugar:x['lowSugar']==true,tags:((x['tags'] as List?)?.whereType<String>().take(20).toList()??const []),status:x['status']??'active');}}
class AurenFoodService { AurenFoodService._(); static final instance=AurenFoodService._(); final _db=FirebaseFirestore.instance;
Stream<List<AurenFoodItem>> watch({String city='',String country='',String category='',bool halalOnly=false,bool organicOnly=false,bool veganOnly=false,bool vegetarianOnly=false,bool athleteOnly=false,bool highProteinOnly=false,bool glutenFreeOnly=false,bool lactoseFreeOnly=false,bool lowSugarOnly=false})=>_db.collection('food_items').where('status',isEqualTo:'active').limit(100).snapshots().map((s){final c=city.trim().toLowerCase(),co=country.trim().toLowerCase(),ca=category.trim().toLowerCase();return s.docs.map(AurenFoodItem.fromDoc).where((x)=>(c.isEmpty||x.city.toLowerCase()==c)&&(co.isEmpty||x.country.toLowerCase()==co)&&(ca.isEmpty||x.category.toLowerCase()==ca)&&( !halalOnly || x.halal)&&( !organicOnly || x.organic)&&( !veganOnly || x.vegan)&&( !vegetarianOnly || x.vegetarian)&&( !athleteOnly || x.athleteFriendly)).toList();});
Future<String> create({required String ownerId,required String name,required String category,required String city,required String country,required String currency,required int priceMinor,required bool halal,required bool organic,required bool vegan,required bool vegetarian,required bool athleteFriendly,bool highProtein=false,bool glutenFree=false,bool lactoseFree=false,bool lowSugar=false})async{if(ownerId.isEmpty||name.trim().isEmpty||city.trim().isEmpty||country.trim().isEmpty)throw ArgumentError('بيانات الطعام الأساسية مطلوبة.');if(priceMinor<0)throw ArgumentError('السعر غير صالح.');final r=_db.collection('food_items').doc();await r.set({'ownerId':ownerId,'name':name.trim(),'category':category.trim(),'city':city.trim(),'country':country.trim(),'currency':currency.trim().toUpperCase(),'priceMinor':priceMinor,'halal':halal,'organic':organic,'vegan':vegan,'vegetarian':vegetarian,'athleteFriendly':athleteFriendly,'highProtein':highProtein,'glutenFree':glutenFree,'lactoseFree':lactoseFree,'lowSugar':lowSugar,'status':'active','createdAt':FieldValue.serverTimestamp()});return r.id;}
}